from functools import lru_cache
import itertools, sys

# types as tuples
TOP=('top',); NAT=('nat',)
def bv(i): return ('bvar',i)
def fv_(x): return ('fvar',x)
def arr(a,b): return ('arrow',a,b)
def mu(a): return ('mu',a)

def open_rec(k,U,T):
    t=T[0]
    if t=='bvar':
        return U if T[1]==k else T
    if t in ('top','nat','fvar'): return T
    if t=='arrow': return ('arrow',open_rec(k,U,T[1]),open_rec(k,U,T[2]))
    if t=='mu': return ('mu',open_rec(k+1,U,T[1]))
def op(T,U): return open_rec(0,U,T)

def subst(x,U,T):
    t=T[0]
    if t=='fvar': return U if T[1]==x else T
    if t in ('top','nat','bvar'): return T
    if t=='arrow': return ('arrow',subst(x,U,T[1]),subst(x,U,T[2]))
    if t=='mu': return ('mu',subst(x,U,T[1]))

def fvs(T):
    t=T[0]
    if t=='fvar': return {T[1]}
    if t in ('top','nat','bvar'): return set()
    if t=='arrow': return fvs(T[1])|fvs(T[2])
    if t=='mu': return fvs(T[1])

def wellscoped(T,d=0):
    t=T[0]
    if t=='bvar': return T[1] < d
    if t in ('top','nat','fvar'): return True
    if t=='arrow': return wellscoped(T[1],d) and wellscoped(T[2],d)
    if t=='mu': return wellscoped(T[1],d+1)

def show(T, names=None):
    names = names or {}
    t=T[0]
    if t=='top': return 'Top'
    if t=='nat': return 'Nat'
    if t=='bvar':
        i=T[1]
        return names.get(i, '#'+str(i))
    if t=='fvar': return str(T[1])
    if t=='arrow': return '('+show(T[1],names)+' -> '+show(T[2],names)+')'
    if t=='mu': return 'mu. '+show(T[1],{k+1:v for k,v in names.items()} if False else {i+1:names.get(i,'#'+str(i)) for i in names}|{0:'@'})

# iso system
def wf_iso(E,A):
    return fvs(A) <= set(E) and wellscoped(A)

def iso(E,A,B,depth=0):
    if depth>40: return None
    if A==NAT and B==NAT: return True
    if B==TOP and wf_iso(E,A): return True
    if A[0]=='fvar' and B[0]=='fvar': return A[1]==B[1] and A[1] in E
    if A[0]=='arrow' and B[0]=='arrow':
        return iso(E,B[1],A[1],depth+1) and iso(E,A[2],B[2],depth+1)
    if A[0]=='mu' and B[0]=='mu':
        a1,a2=A[1],B[1]
        # fresh name
        used=set(E)|fvs(a1)|fvs(a2)
        X=0
        while X in used: X+=1
        E2=[X]+E
        return iso(E2,op(a1,fv_(X)),op(a2,fv_(X)),depth+1) and iso(E2,op(a1,op(a1,fv_(X))),op(a2,op(a2,fv_(X))),depth+1)
    return False

def wf_amber(Ea,T):
    dom=set(itertools.chain(*[(x,y) for x,y in Ea]))
    return fvs(T) <= dom and wellscoped(T)

def wfe_amber(Ea):
    seen=set()
    for x,y in Ea:
        if x in seen or y in seen or x==y: return False
        seen.add(x); seen.add(y)
    return True

def amber(Ea,A,B,depth=0):
    if depth>40: return None
    if not wfe_amber(Ea): return False
    if A==NAT and B==NAT: return True
    if B==TOP and wf_amber(Ea,A): return True
    if A[0]=='fvar' and B[0]=='fvar': return (A[1],B[1]) in Ea
    if A[0]=='arrow' and B[0]=='arrow':
        return amber(Ea,B[1],A[1],depth+1) and amber(Ea,A[2],B[2],depth+1)
    if A[0]=='mu' and B[0]=='mu':
        a1,a2=A[1],B[1]
        used=set(itertools.chain(*[(x,y) for x,y in Ea]))|fvs(a1)|fvs(a2)
        X=0
        while X in used: X+=1
        Y=0
        while Y in used or Y==X: Y+=1
        return amber(Ea+[(X,Y)],op(a1,fv_(X)),op(a2,fv_(Y)),depth+1)
    if A==B and A[0]=='mu' and wf_amber(Ea,A): return True
    return False
