import sys
sys.setrecursionlimit(100000)
sys.path.insert(0,'/tmp/explore')
from sub import *

def gen(size, d=0):
    # generate types with <= size nodes, wellscoped in depth d, possibly with bvars < d
    if size<=0: return []
    res=[]
    if size>=1:
        res.append(TOP); res.append(NAT)
        for i in range(d): res.append(bv(i))
    if size>=3:
        for s1 in range(1,size-1):
            s2=size-1-s1
            for a in gen(s1,d):
                for b in gen(s2,d):
                    if wellscoped(('arrow',a,b),d): res.append(('arrow',a,b))
    if size>=2:
        for s1 in range(1,size):
            for a in gen(s1,d+1):
                if wellscoped(('mu',a),d) and fvs(('mu',a))==set(): res.append(('mu',a))
    # dedupe
    return list(dict.fromkeys(res))

def closed_types(maxsize):
    # types without free atoms and wellscoped
    out=[]
    for s in range(1,maxsize+1):
        for t in gen(s,0):
            if fvs(t)==set() and wellscoped(t): out.append(t)
    return list(dict.fromkeys(out))

for maxsize in [3,4]:
    ts=closed_types(maxsize)
    print("maxsize",maxsize,"num types",len(ts))
    bad=[]
    for A in ts:
        for B in ts:
            i=iso([],A,B); a=amber([],A,B)
            if i and not a: bad.append((A,B))
    print("  iso-true amber-false:",len(bad))
    for A,B in bad[:10]:
        print("   ",show(A),' <: ',show(B))
