    if A[0]=='arrow' and B[0]=='arrow': return iso3(E,B[1],A[1],depth+1) and iso3(E,A[2],B[2],depth+1)
    if A[0]=='mu' and B[0]=='mu':
        a1,a2=A[1],B[1]
        used=set(E)|fvs(a1)|fvs(a2); Z=max(used,default=-1)+1; E2=[Z]+E
        return iso3(E2,op(a1,fv_(Z)),op(a2,fv_(Z)),depth+1) and iso3(E2,op(a1,op(a1,fv_(Z))),op(a2,op(a2,fv_(Z))),depth+1)
    return False
