    if B==TOP and wf_amber(Ea,A): return True
    if A[0]=='fvar' and B[0]=='fvar': return (A[1],B[1]) in Ea
    if A[0]=='arrow' and B[0]=='arrow': return amber3(Ea,B[1],A[1],depth+1) and amber3(Ea,A[2],B[2],depth+1)
    if A[0]=='mu' and B[0]=='mu':
