#!/usr/bin/env python3
# Independent model of iso-recursive `sub` and Amber `sub_amber` for closed types.
# Types: ('top',), ('nat',), ('bv',i), ('fv',a), ('mu',body), ('arrow',t1,t2)
from functools import lru_cache
import sys
sys.setrecursionlimit(100000)

TOP=('top',); NAT=('nat',)

def is_ty(t):
    return isinstance(t,tuple)

def size(t):
    k=t[0]
    if k in ('top','nat','bv','fv'): return 1
    if k=='mu': return 1+size(t[1])
    if k=='arrow': return 1+size(t[1])+size(t[2])
    raise ValueError(t)

def open_rec(K,U,T):
    k=T[0]
    if k=='top' or k=='nat': return T
    if k=='bv': return U if T[1]==K else T
    if k=='fv': return T
    if k=='arrow': return ('arrow', open_rec(K,U,T[1]), open_rec(K,U,T[2]))
    if k=='mu': return ('mu', open_rec(K+1,U,T[1]))
    raise ValueError(T)

def open_tt(T,U): return open_rec(0,U,T)

def fv(T,acc=None):
    if acc is None: acc=set()
    k=T[0]
    if k in ('top','nat','bv'): return acc
    if k=='fv': acc.add(T[1]); return acc
    if k=='arrow': fv(T[1],acc); fv(T[2],acc); return acc
    if k=='mu': return fv(T[1],acc)
    raise ValueError(T)

def lc_rec(d,T):
    k=T[0]
    if k in ('top','nat','fv'): return True
    if k=='bv': return T[1]<d
    if k=='arrow': return lc_rec(d,T[1]) and lc_rec(d,T[2])
    if k=='mu': return lc_rec(d+1,T[1])
    raise ValueError(T)

def lc(T): return lc_rec(0,T)

def subst(T, m):  # apply dict atom->atom renaming
    k=T[0]
    if k in ('top','nat','bv'): return T
    if k=='fv': return ('fv', m.get(T[1],T[1]))
    if k=='arrow': return ('arrow', subst(T[1],m), subst(T[2],m))
    if k=='mu': return ('mu', subst(T[1],m))
    raise ValueError(T)

def canon(state):
    # state = (env_atoms_or_pairs, types...). canonicalize atom labels by first occurrence.
    mp={}
    def la(a):
        if a not in mp: mp[a]=len(mp)
        return mp[a]
    def ct(t):
        k=t[0]
        if k in ('top','nat'): return t
        if k=='bv': return t
        if k=='fv': return ('fv',la(t[1]))
        if k=='arrow': return ('arrow',ct(t[1]),ct(t[2]))
        if k=='mu': return ('mu',ct(t[1]))
        raise ValueError(t)
    env=state[0]
    nenv=[]
    if isinstance(env,list):
        for p in env:
            if isinstance(p,tuple):
                nenv.append((la(p[0]),la(p[1])))
            else:
                nenv.append(la(p))
    else:
        nenv=la(env)
    return tuple([nenv]+[ct(t) for t in state[1:]])

# ---------------- WF (iso) ----------------
# characterization: lc_tt A and fv(A) subset env
def wf_iso(env,A):
    return lc(A) and fv(A)<=set(env)

# ---------------- iso sub proof search (least fixed point, cycle cut) ----------------
class IsoChecker:
    def __init__(self, maxdepth=300, maxsize=4000, node_limit=2_000_000):
        self.maxdepth=maxdepth; self.maxsize=maxsize; self.node_limit=node_limit
        self.nodes=0
    def fresh(self, env, *ts):
        used=set(env)
        for t in ts: used|=fv(t)
        i=0
        while ('a',i) in used: i+=1
        return ('a',i)
    def check(self, env, A, B, path, depth=0):
        self.nodes+=1
        if self.nodes>self.node_limit: return None
        if depth>self.maxdepth: return None
        if size(A)+size(B)>self.maxsize: return None
        st=canon((list(env),A,B))
        if st in path: return False   # cycle: no finite least-fixpoint derivation through it
        path=path|{st}
        # rules
        # nat
        if A==NAT and B==NAT: return True
        # fvar subset (same atom, in env)
        if A[0]=='fv' and B[0]=='fv' and A[1]==B[1] and A[1] in env: return True
        # top
        if B==TOP and wf_iso(env,A): return True
        # arrow
        if A[0]=='arrow' and B[0]=='arrow':
            r1=self.check(env,B[1],A[1],path,depth+1)
            if r1 is False or r1 is None: return r1
            return self.check(env,A[2],B[2],path,depth+1)
        # mu
        if A[0]=='mu' and B[0]=='mu':
            W=self.fresh(env,A[1],B[1])
            env2=[W]+list(env)
            oa=open_tt(A[1],('fv',W)); ob=open_tt(B[1],('fv',W))
            r1=self.check(env2,oa,ob,path,depth+1)
            if r1 is False or r1 is None: return r1
            oa2=open_tt(A[1],oa); ob2=open_tt(B[1],ob)
            return self.check(env2,oa2,ob2,path,depth+1)
        return False

# memo-free cache at top-level different calls; a global memo of True is sound (proof found independent of path? path cycle cut could make a true result path-dependent; but a verified derivation found under a path avoids those states; if we memo True from a search that used assumptions? We cut cycles as False, so any True is a genuine finite derivation independent of path. So memo True sound.)
_iso_true=set(); _iso_false=set(); _iso_unknown=set()

def iso_check(A,B, chk=None):
    if chk is None: chk=IsoChecker()
    st=canon(([],A,B))
    if st in _iso_true: return True
    if st in _iso_false: return False
    if st in _iso_unknown: return None
    chk.nodes=0
    r=chk.check([],A,B,frozenset())
    if r is True: _iso_true.add(st)
    elif r is False: _iso_false.add(st)
    else: _iso_unknown.add(st)
    return r

# ---------------- Amber ----------------
# wf_amber Ea A iff lc A and fv A subset domA Ea
def domA(Ea):
    s=set()
    for (x,y) in Ea: s.add(x); s.add(y)
    return s
def wf_amber(Ea,A): return lc(A) and fv(A)<=domA(Ea)

class AmberChecker:
    def __init__(self, node_limit=3_000_000):
        self.nodes=0; self.node_limit=node_limit
    def fresh2(self, Ea, *ts):
        used=domA(Ea)
        for t in ts: used|=fv(t)
        i=0
        while ('a',i) in used or ('b',i) in used: i+=1
        # choose two distinct atoms
        X=('a',i); Y=('b',i)
        return X,Y
    def check(self, Ea, A, B, assumps):
        # returns True/False/None ; True means coinductive proof with cycles closed by assumps.
        self.nodes+=1
        if self.nodes>self.node_limit: return None
        st=canon((list(Ea),A,B))
        if st in assumps: return True
        assumps=assumps|{st}
        results=[]
        # nat
        if A==NAT and B==NAT: results.append(True)
        # top
        if B==TOP and wf_amber(Ea,A): results.append(True)
        # fvar
        if A[0]=='fv' and B[0]=='fv' and (A[1],B[1]) in Ea: results.append(True)
        # arrow
        if A[0]=='arrow' and B[0]=='arrow':
            r1=self.check(Ea,B[1],A[1],assumps)
            if r1 is True:
                r2=self.check(Ea,A[2],B[2],assumps)
                if r2 is True: results.append(True)
                elif r2 is None: return None
            elif r1 is None: return None
        # mu sam_rec
        if A[0]=='mu' and B[0]=='mu':
            X,Y=self.fresh2(Ea,A[1],B[1])
            Ea2=[(X,Y)]+list(Ea)
            oa=open_tt(A[1],('fv',X)); ob=open_tt(B[1],('fv',Y))
            r=self.check(Ea2,oa,ob,assumps)
            if r is True: results.append(True)
            elif r is None: return None
            # sam_refl
        if A[0]=='mu' and B[0]=='mu' and A==B and wf_amber(Ea,A):
            results.append(True)
        if any(results): return True
        return False

_amber_memo={}
def amber_check(A,B):
    st=canon(([],A,B))
    if st in _amber_memo: return _amber_memo[st]
    chk=AmberChecker()
    r=chk.check([],A,B,frozenset())
    _amber_memo[st]=r
    return r

def amber_check_env(Ea,A,B):
    chk=AmberChecker()
    return chk.check(list(Ea),A,B,frozenset())

# ---------------- closed type enumeration ----------------
def gen(depth, n):
    # generate types of exact size n, locally closed (bvars < depth)
    if n<=0: return
    if n==1:
        yield TOP; yield NAT
        for i in range(depth): yield ('bv',i)
        return
    if n>=2:
        # mu body size n-1 at depth+1
        for b in gen(depth+1,n-1):
            yield ('mu',b)
    # arrow: sizes s1>=1,s2>=1, 1+s1+s2=n
    for s1 in range(1,n-1):
        s2=n-1-s1
        for t1 in gen(depth,s1):
            for t2 in gen(depth,s2):
                yield ('arrow',t1,t2)

def gen_closed(maxn):
    for n in range(1,maxn+1):
        seen=set()
        for t in gen(0,n):
            if lc(t) and not fv(t) and t not in seen:
                seen.add(t); yield t
        print(f'# size {n}: {len(seen)} closed types', file=sys.stderr)

if __name__=='__main__':
    # sanity: the known false amber env judgment
    X=('a',0); Y=('b',0); U=('a',1); V=('b',1)
    body=('arrow',('arrow',('bv',0),('bv',0)),('fv',X))
    body2=('arrow',('arrow',('bv',0),('bv',0)),('fv',Y))
    print('false amber test mu(arrow(arrow 0 0,X)) <: mu(...Y) at [(X,Y)]:',
          amber_check_env([(X,Y)],('mu',body),('mu',body2)))
    # iso diagonal version at env [Z]
    Z=('a',2)
    bi=('arrow',('arrow',('bv',0),('bv',0)),('fv',Z))
    print('iso mu same at env[Z]:', IsoChecker().check([Z],('mu',bi),('mu',bi),frozenset()))
    maxn=int(sys.argv[1]) if len(sys.argv)>1 else 7
    types=list(gen_closed(maxn))
    print('total types',len(types),file=sys.stderr)
    counter=0; isopairs=0
    for A in types:
        for B in types:
            ri=iso_check(A,B)
            if ri is True:
                isopairs+=1
                ra=amber_check(A,B)
                if ra is False:
                    print('COUNTEREXAMPLE:',A,B); counter+=1
                elif ra is None:
                    print('amber unknown',A,B)
    print('iso-true closed pairs:',isopairs,'amber-false:',counter)

