from functools import lru_cache

# Type constructors as tuples
# ('top',), ('nat',), ('bv',n), ('fv',atom), ('arr',a,b), ('mu',t)

def opent(t, x, k=0):
    tag=t[0]
    if tag in ('top','nat'): return t
    if tag=='bv': return ('fv',x) if t[1]==k else t
    if tag=='fv': return t
    if tag=='arr': return ('arr',opent(t[1],x,k),opent(t[2],x,k))
    if tag=='mu': return ('mu',opent(t[1],x,k+1))
    raise ValueError

def atoms(t, acc=None):
    if acc is None: acc=set()
    tag=t[0]
    if tag=='fv': acc.add(t[1])
    elif tag=='arr': atoms(t[1],acc); atoms(t[2],acc)
    elif tag=='mu': atoms(t[1],acc)
    return acc

def bvars_ok(t, d=0):
    tag=t[0]
    if tag in ('top','nat','fv'): return True
    if tag=='bv': return t[1] < d
    if tag=='arr': return bvars_ok(t[1],d) and bvars_ok(t[2],d)
    if tag=='mu': return bvars_ok(t[1],d+1)
    raise ValueError

def lc(t): return bvars_ok(t,0)

def flat(t):
    # flatten for printing
    tag=t[0]
    if tag=='top': return 'Top'
    if tag=='nat': return 'Nat'
    if tag=='bv': return f'#{t[1]}'
    if tag=='fv': return str(t[1])
    if tag=='arr': return f'({flat(t[1])}->{flat(t[2])})'
    if tag=='mu': return f'mu.{flat(t[1])}'
    raise ValueError

def fresh_from(s, prefix='a'):
    i=0
    while f'{prefix}{i}' in s: i+=1
    return f'{prefix}{i}'

def wf_env(E):  # E tuple of atoms, sub bindings
    return len(set(E))==len(E)

def wfe_amber(E): # E tuple of pairs
    xs=[]
    for (x,y) in E: xs += [x,y]
    return len(set(xs))==len(xs)

# WF E A  (Rules.WF)
def WF(E,A):
    if not wf_env(E): return False
    return _WF(frozenset(E), A)

@lru_cache(maxsize=None)
def _WF(E,A):
    tag=A[0]
    if tag in ('top','nat'): return True
    if tag=='fv': return A[1] in E
    if tag=='arr': return _WF(E,A[1]) and _WF(E,A[2])
    if tag=='mu':
