def wf_amber(E,A):
    if not wfe_amber(tuple(E)): return False
    return _wfA(E,A)

@lru_cache(maxsize=None)
def _wfA(E,A):
    tag=A[0]
    if tag in ('top','nat'): return True
    if tag=='fv':
