# generation of locally closed types by size and binder depth
from functools import lru_cache as _lc

def gen(depth, n):
    """set of types of size n, locally closed with bvars < depth"""
    res=set()
    if n<1: return res
    if n==1:
        res.add(('top',)); res.add(('nat',))
        for i in range(depth): res.add(('bv',i))
        return res
    # mu t: size 1 + size(t), t depth+1
    for t in gen(depth+1,n-1): res.add(('mu',t))
    # arrow a b: 1 + sa + sb
    for sa in range(1,n-1):
        sb=n-1-sa
        for a in gen(depth,sa):
            for b in gen(depth,sb):
                res.add(('arr',a,b))
    return res

def closed_types(n): return gen(0,n)

if __name__=='__main__' and False:
    pass
