    if n in memo: return memo[n]
    res=[]
    if n==1: res=[('h',)]
    for i in range(1,n-1):
        for j in range(1,n-i):
            if i+j+1!=n: continue
            for K in genctx(i):
                for S in allside:
                    if size(S)!=j: continue
                    res.append(('a',K,('s',S))); res.append(('a',('s',S),K))
    memo[n]=res; return res
def fill(K,X):
    if K[0]=='h': return X
    if K[0]=='s': return K[1]
    return ('arr',fill(K[1],X),fill(K[2],X))
# replace exactly one closed leaf ('s',S) in K with ('s',S2)
def variants(K):
    out=[]
    if K[0]=='h': return out
    if K[0]=='s':
        for S2 in allside:
            if S2!=K[1]: out.append(('s',S2))
        return out
    for v in variants(K[1]): out.append(('a',v,K[2]))
    for v in variants(K[2]): out.append(('a',K[1],v))
    return out
S=Search(); tested=0; p2ok=0; bad=[]
for cn,C in Cvars.items():
  mC=('mu',C)
  for n1 in range(1,8):
    for K in genctx(n1):
      D1=fill(K,mC); A0=('mu',D1)
      if not (lc(A0) and WF(frozenset(),A0)): continue
      for K2 in variants(K):
        D2=fill(K2,mC); B0=('mu',D2)
        if D1==D2: continue
        if not (lc(B0) and WF(frozenset(),B0)): continue
        tested+=1
        X='z0'; E2=frozenset({X})
