        if not (S.S(E2,U,V)): continue
        U2=openT(D1,U); V2=openT(D2,V)
        if not S.S(E2,U2,V2): continue
        p2ok+=1
        a=S.A(frozenset(),A0,B0)
        if not a:
            bad.append((cn,A0,B0,D1,D2)); print('COUNTER?',cn,flat(A0),flat(B0)); sys.exit()
        if p2ok<=8:
            print('p2ok',cn,'A',a,flat(A0),'|',flat(B0))
